import{_ as a,c as i,o as r,a3 as l}from"./chunks/framework.BurWKwwG.js";const m=JSON.parse('{"title":"Browse & Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"3.3_browse.md","filePath":"3.3_browse.md"}'),t={name:"3.3_browse.md"};function s(n,e,o,c,d,p){return r(),i("div",null,e[0]||(e[0]=[l('<h1 id="browse-analysis" tabindex="-1">Browse &amp; Analysis <a class="header-anchor" href="#browse-analysis" aria-label="Permalink to “Browse &amp; Analysis”">​</a></h1><h2 id="biomarker-browser" tabindex="-1">Biomarker Browser <a class="header-anchor" href="#biomarker-browser" aria-label="Permalink to “Biomarker Browser”">​</a></h2><p>The <a href="/docs/biomarker.html">Biomarker</a> page (<code>/biomarker</code>) provides structured access to curated colorectal cancer biomarker records. Records are displayed in a paginated table with columns covering biomarker name, gene symbol, type, category, cancer stage, experiment method, and more. Use the search bar to filter records by keyword.</p><h2 id="gene-expression-atlas-umap" tabindex="-1">Gene Expression Atlas (UMAP) <a class="header-anchor" href="#gene-expression-atlas-umap" aria-label="Permalink to “Gene Expression Atlas (UMAP)”">​</a></h2><p>The <a href="/docs/explore.html">Gene Expression Atlas</a> (<code>/explore</code>) visualizes single-cell RNA-seq data as interactive UMAP plots.</p><ul><li><strong>Dataset Selection</strong>: Choose from available scRNA-seq datasets</li><li><strong>Cell Type Filter</strong>: Filter cells by annotated cell type</li><li><strong>Gene Expression Overlay</strong>: Enter a gene symbol (with autocomplete) to color-code cells by expression level</li><li><strong>Default Loading</strong>: The UMAP plot loads 10,000 cells by default for performance</li></ul><h2 id="protein-interaction-network" tabindex="-1">Protein Interaction Network <a class="header-anchor" href="#protein-interaction-network" aria-label="Permalink to “Protein Interaction Network”">​</a></h2><p>The <a href="/docs/explore/network.html">Protein Interaction</a> page (<code>/explore/network</code>) displays protein-protein interaction (PPI) networks using Cytoscape.js.</p><ul><li>Interactive network graph with zoom and pan</li><li>Nodes represent proteins, edges represent interactions</li><li>Data sourced from the STRING database</li></ul><h2 id="single-cell-analyses" tabindex="-1">Single-Cell Analyses <a class="header-anchor" href="#single-cell-analyses" aria-label="Permalink to “Single-Cell Analyses”">​</a></h2><p>The <a href="/docs/analysis.html">Analysis</a> page (<code>/analysis</code>) provides seven analysis modules as tabbed sections:</p><h3 id="degs-differential-expressed-genes" tabindex="-1">DEGs (Differential Expressed Genes) <a class="header-anchor" href="#degs-differential-expressed-genes" aria-label="Permalink to “DEGs (Differential Expressed Genes)”">​</a></h3><p>Three sub-tabs:</p><ol><li><strong>Original</strong>: Volcano plot displaying the full dataset as a scatter plot (no pagination), with a paginated data table below. Use the gene search box (with autocomplete) to highlight specific genes.</li><li><strong>By Celltype</strong>: Differential gene analysis grouped by cell type.</li><li><strong>Tumor vs Normal</strong>: Tumor vs Normal comparison of differentially expressed genes.</li></ol><p>All gene search boxes support autocomplete.</p><h3 id="kegg-pathway" tabindex="-1">KEGG Pathway <a class="header-anchor" href="#kegg-pathway" aria-label="Permalink to “KEGG Pathway”">​</a></h3><p>KEGG pathway enrichment analysis displayed as interactive bubble charts. Bubble size indicates gene count, color indicates significance.</p><h3 id="ridge-ranking" tabindex="-1">Ridge Ranking <a class="header-anchor" href="#ridge-ranking" aria-label="Permalink to “Ridge Ranking”">​</a></h3><p>Ridge ranking chart visualization for gene expression distribution across cell types.</p><h3 id="trajectory" tabindex="-1">Trajectory <a class="header-anchor" href="#trajectory" aria-label="Permalink to “Trajectory”">​</a></h3><p>Two sub-sections:</p><ol><li><strong>Cell Trajectory</strong>: Cell trajectory plots. Filter by Cell Type and Plot Type.</li><li><strong>Interactive Pseudotime</strong>: Interactive pseudotime analysis with three modes: <ul><li>By State</li><li>By Pseudotime</li><li>Gene Expression (with gene autocomplete)</li></ul></li></ol><h3 id="cellchat-cell-communication" tabindex="-1">CellChat (Cell Communication) <a class="header-anchor" href="#cellchat-cell-communication" aria-label="Permalink to “CellChat (Cell Communication)”">​</a></h3><p>Two views:</p><ol><li><strong>All Interactions</strong>: Full cell-cell communication network graph</li><li><strong>Biomarker as Ligand / Receptor</strong>: Enter a gene symbol to view its specific ligand or receptor interaction networks</li></ol><h3 id="network-sensitivity" tabindex="-1">Network Sensitivity <a class="header-anchor" href="#network-sensitivity" aria-label="Permalink to “Network Sensitivity”">​</a></h3><p>PRS (Polygenic Risk Score) network sensitivity analysis. Enter a gene symbol (with autocomplete) to visualize the network sensitivity results.</p><h3 id="predictive-ability" tabindex="-1">Predictive Ability <a class="header-anchor" href="#predictive-ability" aria-label="Permalink to “Predictive Ability”">​</a></h3><p>ROC curve analysis for predictive ability assessment. Two sub-tabs:</p><ol><li><strong>Tumor vs Normal</strong>: ROC analysis comparing tumor and normal samples</li><li><strong>By Celltype</strong>: ROC analysis grouped by cell type</li></ol><p>Features gene autocomplete and AUC value filtering.</p><h2 id="clinical-analysis" tabindex="-1">Clinical Analysis <a class="header-anchor" href="#clinical-analysis" aria-label="Permalink to “Clinical Analysis”">​</a></h2><h3 id="survival-analysis" tabindex="-1">Survival Analysis <a class="header-anchor" href="#survival-analysis" aria-label="Permalink to “Survival Analysis”">​</a></h3><p>The <a href="/docs/clinical/survival.html">Survival</a> page (<code>/clinical/survival</code>) provides Kaplan-Meier survival curves.</p><ul><li>Filter by gene symbol (with autocomplete)</li><li>Filter by clinical parameters (e.g., cancer stage, gender, age group)</li><li>Compare survival curves between high and low expression groups</li></ul><h3 id="immune-infiltration" tabindex="-1">Immune Infiltration <a class="header-anchor" href="#immune-infiltration" aria-label="Permalink to “Immune Infiltration”">​</a></h3><p>The <a href="/docs/clinical/immune.html">Immune</a> page (<code>/clinical/immune</code>) displays an immune infiltration heatmap.</p><ul><li>Renders full data (no pagination)</li><li>Fixed 800px height</li><li>X-axis labels rotated 45 degrees for readability</li></ul><h2 id="data-export" tabindex="-1">Data Export <a class="header-anchor" href="#data-export" aria-label="Permalink to “Data Export”">​</a></h2><p>Charts throughout the platform can be exported as images (PNG/SVG) using the built-in ECharts or Cytoscape.js export functionality.</p>',40)]))}const g=a(t,[["render",s]]);export{m as __pageData,g as default};
